{
  "name": "opencode-token-ledger",
  "version": "0.5.2",
  "description": "Lokales Dashboard für den Tokenverbrauch von OpenCode – API und Frontend auf einem Port, startbar via opencode-token-ledger.",
  "type": "module",
  "main": "dist/plugin.js",
  "types": "dist/plugin.d.ts",
  "exports": {
    "./server": "./dist/plugin.js",
    ".": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    },
    "./package.json": "./package.json"
  },
  "bin": {
    "opencode-token-ledger": "dist/cli.js"
  },
  "files": [
    "dist",
    "public"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "token-usage",
    "dashboard"
  ],
  "engines": {
    "node": ">=22"
  },
  "dependencies": {
    "@hono/node-server": "^1.19.8",
    "hono": "^4.13.3"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/node": "^24.10.1",
    "tsx": "^4.21.0",
    "typescript": "^5.9.3"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "scripts": {
    "dev": "tsx watch src/index.ts",
    "start": "node dist/index.js",
    "build": "tsc -p tsconfig.json",
    "check": "tsc -p tsconfig.json --noEmit",
    "test": "tsc -p tsconfig.json && tsx --test test/*.test.ts"
  }
}
